-- RentOS: full schema, all migrations in order. GENERATED by
-- scripts/build-setup-sql.mjs -- edit the files in supabase/migrations/ instead.
-- Paste into Supabase Dashboard -> SQL Editor -> New query -> Run.
-- Run it ONCE on an empty project; re-running will error on "already exists".

-- ===== 20260101000000_extensions.sql =====
-- Extensions used across later migrations. `extensions` already exists on
-- every real Supabase project; created here only so this migration also
-- works against a plain Postgres instance (e.g. the local RLS test harness).
create schema if not exists extensions;
create extension if not exists "pgcrypto" with schema extensions;


-- ===== 20260101000100_enums.sql =====
-- Enumerated types shared across the schema. Keeping these as real Postgres
-- enums (rather than free text) means invalid values are rejected by the
-- database itself, not just by application code.

create type public.account_role as enum ('owner', 'receptionist', 'worker', 'member');

create type public.vehicle_type as enum ('car', 'truck', 'suv', 'van', 'motorcycle');

create type public.vehicle_status as enum ('available', 'rented', 'service');

create type public.fuel_type as enum ('gasoline', 'diesel', 'electric', 'hybrid', 'other');

create type public.level_source as enum ('manual', 'photo', 'obd', 'api');

create type public.reservation_status as enum (
  'pending', 'confirmed', 'cancelled', 'completed', 'no_show'
);

create type public.rental_status as enum ('active', 'completed');

create type public.extra_item_type as enum ('equipment', 'service', 'additional_driver', 'insurance');

create type public.payment_method as enum ('card', 'cash', 'other');

create type public.payment_status as enum ('pending', 'succeeded', 'failed', 'refunded');

create type public.notification_type as enum (
  'pickup_reminder', 'due_soon', 'overdue', 'reservation_cancelled',
  'service_due', 'insurance_expiring'
);

create type public.notification_channel as enum ('email', 'sms', 'whatsapp', 'telegram', 'push');

create type public.notification_status as enum ('queued', 'sent', 'failed');

create type public.expense_category as enum ('repair', 'insurance', 'fuel', 'wash', 'fine');

create type public.vehicle_log_event as enum (
  'status_change', 'inspection', 'service', 'note', 'pickup', 'return'
);


-- ===== 20260101000200_tenancy.sql =====
-- Tenancy: companies, locations, and the accounts that link auth.users to a
-- company with a role. Every other table in the schema carries company_id
-- and is locked down by RLS policies defined in 20260101000900_rls.sql.

create table public.companies (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 200),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  default_currency text not null check (default_currency ~ '^[A-Z]{3}$'),
  default_locale text not null default 'en',
  timezone text not null default 'UTC',
  tax_rate_bps integer not null default 0 check (tax_rate_bps between 0 and 10000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on column public.companies.tax_rate_bps is 'Tax rate in basis points (100 = 1%). A per-company setting, never hardcoded.';

create table public.locations (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 200),
  address text not null default '',
  timezone text not null default 'UTC',
  created_at timestamptz not null default now()
);

create table public.accounts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  company_id uuid not null references public.companies (id) on delete cascade,
  role public.account_role not null,
  full_name text not null default '',
  phone text,
  created_at timestamptz not null default now(),
  unique (user_id, company_id)
);

create index locations_company_id_idx on public.locations (company_id);
create index accounts_company_id_idx on public.accounts (company_id);
create index accounts_user_id_idx on public.accounts (user_id);

-- Keep updated_at current without trusting the client to set it.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger companies_set_updated_at
  before update on public.companies
  for each row execute function public.set_updated_at();


-- ===== 20260101000300_auth_helpers.sql =====
-- Helper functions used by RLS policies. Each is SECURITY DEFINER so it reads
-- public.accounts as its owner (bypassing RLS on that read) instead of
-- re-entering the accounts table's own policies -- that indirection is what
-- avoids infinite recursion when accounts.sql's own policies call these.

create or replace function public.current_company_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select company_id from public.accounts where user_id = auth.uid();
$$;

create or replace function public.current_role_in_company(target_company_id uuid)
returns public.account_role
language sql
stable
security definer
set search_path = public
as $$
  select role from public.accounts
  where user_id = auth.uid() and company_id = target_company_id
  limit 1;
$$;

create or replace function public.is_staff_in_company(target_company_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.accounts
    where user_id = auth.uid()
      and company_id = target_company_id
      and role in ('owner', 'receptionist', 'worker')
  );
$$;

create or replace function public.my_account_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select id from public.accounts where user_id = auth.uid();
$$;

revoke all on function public.current_company_ids() from public;
revoke all on function public.current_role_in_company(uuid) from public;
revoke all on function public.is_staff_in_company(uuid) from public;
revoke all on function public.my_account_ids() from public;
grant execute on function public.current_company_ids() to authenticated;
grant execute on function public.current_role_in_company(uuid) to authenticated;
grant execute on function public.is_staff_in_company(uuid) to authenticated;
grant execute on function public.my_account_ids() to authenticated;


-- ===== 20260101000400_create_company.sql =====
-- The only way to create a company. Companies and accounts have no INSERT
-- policy (see 20260101000900_rls.sql) so a signed-in user cannot insert an
-- accounts row for themselves with an arbitrary role or company_id -- this
-- function is the sole, controlled path, and it always makes the caller the
-- new company's owner.
create or replace function public.create_company(
  p_name text,
  p_slug text,
  p_default_currency text,
  p_default_locale text default 'en',
  p_timezone text default 'UTC'
)
returns public.companies
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company public.companies;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  insert into public.companies (name, slug, default_currency, default_locale, timezone)
  values (p_name, p_slug, p_default_currency, p_default_locale, p_timezone)
  returning * into v_company;

  insert into public.accounts (user_id, company_id, role, full_name)
  values (auth.uid(), v_company.id, 'owner', coalesce(auth.jwt() ->> 'name', ''));

  return v_company;
end;
$$;

revoke all on function public.create_company(text, text, text, text, text) from public;
grant execute on function public.create_company(text, text, text, text, text) to authenticated;


-- ===== 20260101000500_vehicles.sql =====
-- Fleet: vehicles and their event log. subtype is validated against type
-- with a check constraint rather than a second enum, since the set of valid
-- subtypes depends on the type.

create table public.vehicles (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  location_id uuid references public.locations (id) on delete set null,
  barcode text not null,
  license_plate text not null,
  model text not null,
  type public.vehicle_type not null,
  subtype text not null,
  color text not null default '',
  parking_stall text,
  status public.vehicle_status not null default 'available',
  odometer integer not null default 0 check (odometer >= 0),
  fuel_type public.fuel_type not null,
  fuel_or_charge_level numeric(5, 2) not null default 100 check (fuel_or_charge_level between 0 and 100),
  level_source public.level_source not null default 'manual',
  model_glb_key text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (company_id, barcode),
  constraint vehicles_subtype_matches_type check (
    (type = 'car' and subtype in ('sedan', 'hatchback', 'coupe')) or
    (type = 'truck' and subtype in ('pickup', 'box_truck')) or
    (type = 'suv' and subtype in ('compact', 'full_size')) or
    (type = 'van' and subtype in ('passenger', 'cargo')) or
    (type = 'motorcycle' and subtype in ('standard', 'touring'))
  )
);

create index vehicles_company_id_idx on public.vehicles (company_id);
create index vehicles_company_status_idx on public.vehicles (company_id, status);

create trigger vehicles_set_updated_at
  before update on public.vehicles
  for each row execute function public.set_updated_at();

create table public.vehicle_logs (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  vehicle_id uuid not null references public.vehicles (id) on delete cascade,
  event_type public.vehicle_log_event not null,
  actor_account_id uuid references public.accounts (id) on delete set null,
  occurred_at timestamptz not null default now(),
  payload jsonb not null default '{}'::jsonb
);

create index vehicle_logs_company_id_idx on public.vehicle_logs (company_id);
create index vehicle_logs_vehicle_id_idx on public.vehicle_logs (vehicle_id, occurred_at desc);


-- ===== 20260101000600_reservations_and_rentals.sql =====
-- Reservations (booked ahead of time) and rentals (an actual pickup-to-return
-- period). A rental usually originates from a reservation, but reservation_id
-- is nullable to allow a walk-in rental with no prior reservation.
--
-- Money is always integer minor units + an ISO currency code, never a float.
-- tariff_snapshot freezes the tariff that applied when the reservation/rental
-- was created, so changing a company's prices later never rewrites history.

create table public.reservations (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  vehicle_id uuid not null references public.vehicles (id) on delete restrict,
  location_id uuid references public.locations (id) on delete set null,
  member_account_id uuid not null references public.accounts (id) on delete cascade,
  created_by_account_id uuid references public.accounts (id) on delete set null,
  status public.reservation_status not null default 'pending',
  start_at timestamptz not null,
  end_at timestamptz not null check (end_at > start_at),
  tariff_snapshot jsonb not null default '{}'::jsonb,
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  subtotal_minor integer not null default 0 check (subtotal_minor >= 0),
  tax_minor integer not null default 0 check (tax_minor >= 0),
  total_minor integer not null default 0 check (total_minor >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index reservations_company_id_idx on public.reservations (company_id);
create index reservations_vehicle_id_idx on public.reservations (vehicle_id, start_at);
create index reservations_member_account_id_idx on public.reservations (member_account_id);

create trigger reservations_set_updated_at
  before update on public.reservations
  for each row execute function public.set_updated_at();

create table public.rentals (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  reservation_id uuid references public.reservations (id) on delete set null,
  vehicle_id uuid not null references public.vehicles (id) on delete restrict,
  member_account_id uuid not null references public.accounts (id) on delete cascade,
  status public.rental_status not null default 'active',
  started_at timestamptz not null default now(),
  ended_at timestamptz check (ended_at is null or ended_at >= started_at),
  odometer_start integer not null check (odometer_start >= 0),
  odometer_end integer check (odometer_end is null or odometer_end >= odometer_start),
  tariff_snapshot jsonb not null default '{}'::jsonb,
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  late_fee_minor integer not null default 0 check (late_fee_minor >= 0),
  extras_minor integer not null default 0 check (extras_minor >= 0),
  subtotal_minor integer not null default 0 check (subtotal_minor >= 0),
  tax_minor integer not null default 0 check (tax_minor >= 0),
  total_minor integer not null default 0 check (total_minor >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint rentals_ended_fields_consistent check (
    (status = 'active' and ended_at is null) or
    (status = 'completed' and ended_at is not null and odometer_end is not null)
  )
);

create index rentals_company_id_idx on public.rentals (company_id);
create index rentals_vehicle_id_idx on public.rentals (vehicle_id);
create index rentals_member_account_id_idx on public.rentals (member_account_id);
-- At most one active rental per vehicle at a time.
create unique index rentals_one_active_per_vehicle_idx on public.rentals (vehicle_id) where status = 'active';

create trigger rentals_set_updated_at
  before update on public.rentals
  for each row execute function public.set_updated_at();

-- Equipment, services, additional drivers and insurance all attach to a
-- reservation and/or the rental it became, sharing the same (type, cost,
-- details) shape from the domain model.
create table public.rental_extras (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  reservation_id uuid references public.reservations (id) on delete cascade,
  rental_id uuid references public.rentals (id) on delete cascade,
  item_type public.extra_item_type not null,
  label text not null,
  cost_minor integer not null default 0 check (cost_minor >= 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint rental_extras_attached_to_something check (
    reservation_id is not null or rental_id is not null
  )
);

create index rental_extras_company_id_idx on public.rental_extras (company_id);
create index rental_extras_reservation_id_idx on public.rental_extras (reservation_id);
create index rental_extras_rental_id_idx on public.rental_extras (rental_id);


-- ===== 20260101000700_payments_notifications_expenses.sql =====
create table public.payments (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  reservation_id uuid references public.reservations (id) on delete set null,
  rental_id uuid references public.rentals (id) on delete set null,
  amount_minor integer not null check (amount_minor >= 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  method public.payment_method not null,
  status public.payment_status not null default 'pending',
  provider text not null default 'manual',
  provider_payment_id text,
  created_at timestamptz not null default now(),
  constraint payments_attached_to_something check (
    reservation_id is not null or rental_id is not null
  )
);

create index payments_company_id_idx on public.payments (company_id);
create index payments_reservation_id_idx on public.payments (reservation_id);
create index payments_rental_id_idx on public.payments (rental_id);
-- A given provider payment id (e.g. a Stripe PaymentIntent) is only ever recorded once.
create unique index payments_provider_payment_id_idx
  on public.payments (provider, provider_payment_id)
  where provider_payment_id is not null;

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  account_id uuid not null references public.accounts (id) on delete cascade,
  type public.notification_type not null,
  channel public.notification_channel not null,
  content jsonb not null default '{}'::jsonb,
  status public.notification_status not null default 'queued',
  created_at timestamptz not null default now(),
  sent_at timestamptz
);

create index notifications_company_id_idx on public.notifications (company_id);
create index notifications_account_id_idx on public.notifications (account_id, created_at desc);

create table public.expenses (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  vehicle_id uuid not null references public.vehicles (id) on delete cascade,
  category public.expense_category not null,
  amount_minor integer not null check (amount_minor >= 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  occurred_on date not null default current_date,
  notes text not null default '',
  created_by_account_id uuid references public.accounts (id) on delete set null,
  created_at timestamptz not null default now()
);

create index expenses_company_id_idx on public.expenses (company_id);
create index expenses_vehicle_id_idx on public.expenses (vehicle_id, occurred_on desc);


-- ===== 20260101000800_guards.sql =====
-- Field-tampering guards (security checklist #8): a client must never be
-- able to move a row to a different company, or hand themselves a role,
-- purely by sending different values in an UPDATE. RLS's WITH CHECK limits
-- *which* rows are reachable; these triggers additionally freeze specific
-- columns regardless of which row is being updated.

create or replace function public.forbid_company_id_change()
returns trigger
language plpgsql
as $$
begin
  if new.company_id <> old.company_id then
    raise exception 'company_id cannot be changed after creation';
  end if;
  return new;
end;
$$;

create trigger locations_forbid_company_id_change
  before update on public.locations
  for each row execute function public.forbid_company_id_change();

create trigger vehicles_forbid_company_id_change
  before update on public.vehicles
  for each row execute function public.forbid_company_id_change();

create trigger reservations_forbid_company_id_change
  before update on public.reservations
  for each row execute function public.forbid_company_id_change();

create trigger rentals_forbid_company_id_change
  before update on public.rentals
  for each row execute function public.forbid_company_id_change();

create trigger expenses_forbid_company_id_change
  before update on public.expenses
  for each row execute function public.forbid_company_id_change();

-- accounts needs its own guard: user_id is just as immutable as company_id,
-- and role may only change at an owner's hand.
create or replace function public.accounts_guard_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.user_id <> old.user_id or new.company_id <> old.company_id then
    raise exception 'user_id and company_id cannot be changed';
  end if;
  if new.role <> old.role and public.current_role_in_company(old.company_id) <> 'owner' then
    raise exception 'only an owner can change account roles';
  end if;
  return new;
end;
$$;

create trigger accounts_guard_update
  before update on public.accounts
  for each row execute function public.accounts_guard_update();


-- ===== 20260101000900_rls.sql =====
-- Row Level Security for every table. FORCE ROW LEVEL SECURITY makes the
-- policies apply even to the table owner over PostgREST, so the only way
-- around RLS is the service-role key (src/lib/supabase/admin.ts), which never
-- reaches the browser.

alter table public.companies enable row level security;
alter table public.companies force row level security;
alter table public.locations enable row level security;
alter table public.locations force row level security;
alter table public.accounts enable row level security;
alter table public.accounts force row level security;
alter table public.vehicles enable row level security;
alter table public.vehicles force row level security;
alter table public.vehicle_logs enable row level security;
alter table public.vehicle_logs force row level security;
alter table public.reservations enable row level security;
alter table public.reservations force row level security;
alter table public.rentals enable row level security;
alter table public.rentals force row level security;
alter table public.rental_extras enable row level security;
alter table public.rental_extras force row level security;
alter table public.payments enable row level security;
alter table public.payments force row level security;
alter table public.notifications enable row level security;
alter table public.notifications force row level security;
alter table public.expenses enable row level security;
alter table public.expenses force row level security;

-- companies: visible to any member of the company. No INSERT policy -- the
-- only path in is create_company(). Only an owner may update settings.
create policy companies_select on public.companies
  for select to authenticated
  using (id in (select public.current_company_ids()));

create policy companies_update_by_owner on public.companies
  for update to authenticated
  using (public.current_role_in_company(id) = 'owner')
  with check (public.current_role_in_company(id) = 'owner');

-- locations: readable by anyone in the company (members need pickup
-- addresses too); writable by staff only.
create policy locations_select on public.locations
  for select to authenticated
  using (company_id in (select public.current_company_ids()));

create policy locations_write_by_staff on public.locations
  for all to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));

-- accounts: everyone can see their own row; staff can see every account in
-- their company (teammates and members). No INSERT policy -- rows are only
-- created via create_company() or a future invite-acceptance function.
create policy accounts_select on public.accounts
  for select to authenticated
  using (user_id = auth.uid() or public.is_staff_in_company(company_id));

create policy accounts_update on public.accounts
  for update to authenticated
  using (user_id = auth.uid() or public.is_staff_in_company(company_id))
  with check (company_id in (select public.current_company_ids()));

-- vehicles: catalog is readable by anyone in the company (members browse
-- inventory to reserve); only staff can add/edit/retire vehicles.
create policy vehicles_select on public.vehicles
  for select to authenticated
  using (company_id in (select public.current_company_ids()));

create policy vehicles_write_by_staff on public.vehicles
  for all to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));

-- vehicle_logs: internal operational history -- staff only, both ways.
create policy vehicle_logs_staff_only on public.vehicle_logs
  for all to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));

-- reservations: staff see and manage every reservation in their company;
-- a member sees and manages only their own.
create policy reservations_select on public.reservations
  for select to authenticated
  using (
    public.is_staff_in_company(company_id)
    or member_account_id in (select public.my_account_ids())
  );

create policy reservations_insert on public.reservations
  for insert to authenticated
  with check (
    public.is_staff_in_company(company_id)
    or member_account_id in (select public.my_account_ids())
  );

create policy reservations_update on public.reservations
  for update to authenticated
  using (
    public.is_staff_in_company(company_id)
    or member_account_id in (select public.my_account_ids())
  )
  with check (
    public.is_staff_in_company(company_id)
    or member_account_id in (select public.my_account_ids())
  );

-- rentals: same shape as reservations. No member-facing INSERT: a rental is
-- only ever opened by staff at pickup (see Phase 2).
create policy rentals_select on public.rentals
  for select to authenticated
  using (
    public.is_staff_in_company(company_id)
    or member_account_id in (select public.my_account_ids())
  );

create policy rentals_write_by_staff on public.rentals
  for insert to authenticated
  with check (public.is_staff_in_company(company_id));

create policy rentals_update_by_staff on public.rentals
  for update to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));

-- rental_extras: visibility follows the parent reservation/rental.
create policy rental_extras_select on public.rental_extras
  for select to authenticated
  using (
    public.is_staff_in_company(company_id)
    or exists (
      select 1 from public.reservations r
      where r.id = rental_extras.reservation_id
        and r.member_account_id in (select public.my_account_ids())
    )
    or exists (
      select 1 from public.rentals rt
      where rt.id = rental_extras.rental_id
        and rt.member_account_id in (select public.my_account_ids())
    )
  );

create policy rental_extras_write_by_staff on public.rental_extras
  for all to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));

-- payments: same visibility shape as rental_extras; writes happen server-side
-- (Stripe webhooks via the service-role client) or by staff for cash/manual.
create policy payments_select on public.payments
  for select to authenticated
  using (
    public.is_staff_in_company(company_id)
    or exists (
      select 1 from public.reservations r
      where r.id = payments.reservation_id
        and r.member_account_id in (select public.my_account_ids())
    )
    or exists (
      select 1 from public.rentals rt
      where rt.id = payments.rental_id
        and rt.member_account_id in (select public.my_account_ids())
    )
  );

create policy payments_write_by_staff on public.payments
  for all to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));

-- notifications: a recipient sees their own; staff sees all in the company
-- (to debug delivery). Notifications are otherwise written by the server
-- (service-role), not by end users.
create policy notifications_select on public.notifications
  for select to authenticated
  using (
    account_id in (select public.my_account_ids())
    or public.is_staff_in_company(company_id)
  );

-- expenses: fully internal, staff only.
create policy expenses_staff_only on public.expenses
  for all to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));


-- ===== 20260102000000_vehicle_log_trigger.sql =====
-- Automatically logs every vehicle status change to vehicle_logs, so "track
-- all vehicle events" (domain model #9) can't be skipped by forgetting to
-- call a log function from application code -- it happens at the database
-- layer whenever vehicles.status actually changes.
create or replace function public.log_vehicle_status_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_account_id uuid;
begin
  if new.status is distinct from old.status then
    select id into v_actor_account_id
    from public.accounts
    where user_id = auth.uid() and company_id = new.company_id
    limit 1;

    insert into public.vehicle_logs (company_id, vehicle_id, event_type, actor_account_id, payload)
    values (
      new.company_id,
      new.id,
      'status_change',
      v_actor_account_id,
      jsonb_build_object('from', old.status, 'to', new.status)
    );
  end if;
  return new;
end;
$$;

create trigger vehicles_log_status_change
  after update on public.vehicles
  for each row execute function public.log_vehicle_status_change();


-- ===== 20260103000000_tariffs.sql =====
-- Pricing. Phase 0 added `tariff_snapshot jsonb` columns to reservations and
-- rentals (to freeze a tariff at the moment it's used) but never added
-- anywhere to actually define one -- this is that.
--
-- One tariff per (company, vehicle_type); vehicle_type IS NULL is the
-- company-wide default used when no per-type tariff exists.

create table public.tariffs (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  vehicle_type public.vehicle_type,
  name text not null default '',
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  hourly_rate_minor integer not null check (hourly_rate_minor >= 0),
  daily_rate_minor integer not null check (daily_rate_minor >= 0),
  weekly_rate_minor integer not null check (weekly_rate_minor >= 0),
  grace_period_minutes integer not null default 15 check (grace_period_minutes >= 0),
  late_fee_per_hour_minor integer not null check (late_fee_per_hour_minor >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (company_id, vehicle_type)
);

-- unique(company_id, vehicle_type) alone doesn't stop two company-wide
-- defaults (NULL <> NULL for uniqueness purposes), so that case needs its
-- own partial index.
create unique index tariffs_one_default_per_company_idx on public.tariffs (company_id) where vehicle_type is null;

create index tariffs_company_id_idx on public.tariffs (company_id);

create trigger tariffs_set_updated_at
  before update on public.tariffs
  for each row execute function public.set_updated_at();

create trigger tariffs_forbid_company_id_change
  before update on public.tariffs
  for each row execute function public.forbid_company_id_change();

alter table public.tariffs enable row level security;
alter table public.tariffs force row level security;

create policy tariffs_select on public.tariffs
  for select to authenticated
  using (company_id in (select public.current_company_ids()));

create policy tariffs_write_by_staff on public.tariffs
  for all to authenticated
  using (public.is_staff_in_company(company_id))
  with check (public.is_staff_in_company(company_id));


-- ===== 20260103000100_booking_calendar.sql =====
-- Calendar: a vehicle can never have two active (pending/confirmed)
-- reservations that overlap in time. Enforced as a DB constraint, not just
-- app-level validation, using a GiST exclusion constraint over the
-- reservation's time range. btree_gist is what lets a GiST index also
-- compare the plain uuid vehicle_id for equality.
create extension if not exists btree_gist with schema extensions;

alter table public.reservations
  add column during tstzrange generated always as (tstzrange(start_at, end_at, '[)')) stored;

alter table public.reservations
  add constraint reservations_no_overlap exclude using gist (
    vehicle_id with =,
    during with &&
  )
  where (status in ('pending', 'confirmed'));

-- A rental started without a reservation (a walk-in) still needs an expected
-- return time to measure lateness against; one started from a reservation
-- inherits its end_at into here at checkout time instead of re-deriving it
-- later (so changing/cancelling the reservation afterward can't retroactively
-- change what an in-progress rental owes).
alter table public.rentals add column expected_return_at timestamptz;


-- ===== 20260103000200_vehicle_profit_report.sql =====
-- Revenue/profit per vehicle for a period. Plain SQL function (not
-- SECURITY DEFINER) so it runs with the caller's own privileges -- RLS on
-- `rentals` and `expenses` still applies exactly as if the caller had
-- queried those tables directly; this only exists because PostgREST can't
-- express a GROUP BY aggregation through the normal table API.
create or replace function public.vehicle_profit_report(
  p_company_id uuid,
  p_from timestamptz,
  p_to timestamptz
)
returns table (
  vehicle_id uuid,
  model text,
  license_plate text,
  revenue_minor bigint,
  expenses_minor bigint,
  profit_minor bigint,
  rental_count bigint
)
language sql
stable
security invoker
set search_path = public
as $$
  select
    v.id as vehicle_id,
    v.model,
    v.license_plate,
    coalesce(r.revenue_minor, 0) as revenue_minor,
    coalesce(e.expenses_minor, 0) as expenses_minor,
    coalesce(r.revenue_minor, 0) - coalesce(e.expenses_minor, 0) as profit_minor,
    coalesce(r.rental_count, 0) as rental_count
  from public.vehicles v
  left join (
    select vehicle_id, sum(total_minor) as revenue_minor, count(*) as rental_count
    from public.rentals
    where company_id = p_company_id
      and status = 'completed'
      and ended_at >= p_from
      and ended_at < p_to
    group by vehicle_id
  ) r on r.vehicle_id = v.id
  left join (
    select vehicle_id, sum(amount_minor) as expenses_minor
    from public.expenses
    where company_id = p_company_id
      and occurred_on >= p_from::date
      and occurred_on < p_to::date
    group by vehicle_id
  ) e on e.vehicle_id = v.id
  where v.company_id = p_company_id
  order by profit_minor desc;
$$;

revoke all on function public.vehicle_profit_report(uuid, timestamptz, timestamptz) from public;
grant execute on function public.vehicle_profit_report(uuid, timestamptz, timestamptz) to authenticated;


-- ===== 20260104000000_public_booking.sql =====
-- Public booking surface. Visitors browsing a company's booking page are
-- the `anon` role -- not authenticated, not a company member -- and the
-- rest of the schema's RLS policies correctly give them zero access.
-- Rather than opening new RLS policies on the real tables (which would mean
-- reasoning about anon access on every future column added to vehicles/
-- companies/tariffs), the public surface is a small set of SECURITY
-- DEFINER functions that each return only the specific, curated columns a
-- public page actually needs. anon gets no table grants at all; only
-- execute on these functions.

create or replace function public.public_company_by_slug(p_slug text)
returns table (id uuid, name text, default_currency text, default_locale text, timezone text, tax_rate_bps integer)
language sql
stable
security definer
set search_path = public
as $$
  select id, name, default_currency, default_locale, timezone, tax_rate_bps
  from public.companies
  where slug = p_slug;
$$;

create or replace function public.search_available_vehicles(
  p_company_slug text,
  p_start_at timestamptz,
  p_end_at timestamptz,
  p_type public.vehicle_type default null
)
returns table (
  vehicle_id uuid,
  model text,
  type public.vehicle_type,
  subtype text,
  color text,
  fuel_type public.fuel_type,
  model_glb_key text
)
language sql
stable
security definer
set search_path = public
as $$
  select v.id, v.model, v.type, v.subtype, v.color, v.fuel_type, v.model_glb_key
  from public.vehicles v
  join public.companies c on c.id = v.company_id and c.slug = p_company_slug
  where v.status <> 'service'
    and (p_type is null or v.type = p_type)
    and p_end_at > p_start_at
    and not exists (
      select 1 from public.reservations r
      where r.vehicle_id = v.id
        and r.status in ('pending', 'confirmed')
        and r.during && tstzrange(p_start_at, p_end_at, '[)')
    )
  order by v.type, v.model;
$$;

create or replace function public.public_vehicle_by_id(p_vehicle_id uuid)
returns table (
  vehicle_id uuid,
  company_id uuid,
  model text,
  type public.vehicle_type,
  subtype text,
  color text,
  fuel_type public.fuel_type,
  model_glb_key text
)
language sql
stable
security definer
set search_path = public
as $$
  select v.id, v.company_id, v.model, v.type, v.subtype, v.color, v.fuel_type, v.model_glb_key
  from public.vehicles v
  where v.id = p_vehicle_id and v.status <> 'service';
$$;

revoke all on function public.public_vehicle_by_id(uuid) from public;
grant execute on function public.public_vehicle_by_id(uuid) to anon, authenticated;

create or replace function public.public_tariff_for_vehicle_type(
  p_company_slug text,
  p_vehicle_type public.vehicle_type
)
returns table (
  hourly_rate_minor integer,
  daily_rate_minor integer,
  weekly_rate_minor integer,
  currency text,
  grace_period_minutes integer,
  late_fee_per_hour_minor integer
)
language sql
stable
security definer
set search_path = public
as $$
  select t.hourly_rate_minor, t.daily_rate_minor, t.weekly_rate_minor, t.currency,
         t.grace_period_minutes, t.late_fee_per_hour_minor
  from public.tariffs t
  join public.companies c on c.id = t.company_id
  where c.slug = p_company_slug
    and (t.vehicle_type = p_vehicle_type or t.vehicle_type is null)
  order by t.vehicle_type nulls last
  limit 1;
$$;

revoke all on function public.public_company_by_slug(text) from public;
revoke all on function public.search_available_vehicles(text, timestamptz, timestamptz, public.vehicle_type) from public;
revoke all on function public.public_tariff_for_vehicle_type(text, public.vehicle_type) from public;
grant execute on function public.public_company_by_slug(text) to anon, authenticated;
grant execute on function public.search_available_vehicles(text, timestamptz, timestamptz, public.vehicle_type) to anon, authenticated;
grant execute on function public.public_tariff_for_vehicle_type(text, public.vehicle_type) to anon, authenticated;

-- The only way a signed-in visitor becomes a member of a company they're
-- booking with. Deliberately narrow: it can only create the lowest-
-- privilege role ('member'), only for the caller's own auth.uid(), only
-- for a company that already exists -- no way to escalate role or target
-- another user, unlike a general-purpose accounts INSERT would allow.
create or replace function public.join_company_as_member(p_company_slug text)
returns public.accounts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company_id uuid;
  v_account public.accounts;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select id into v_company_id from public.companies where slug = p_company_slug;
  if v_company_id is null then
    raise exception 'company not found';
  end if;

  select * into v_account from public.accounts where user_id = auth.uid() and company_id = v_company_id;
  if found then
    return v_account;
  end if;

  insert into public.accounts (user_id, company_id, role, full_name)
  values (auth.uid(), v_company_id, 'member', coalesce(auth.jwt() ->> 'name', ''))
  returning * into v_account;

  return v_account;
end;
$$;

-- A new function gets EXECUTE granted to PUBLIC (and, on this project's
-- default privileges, directly to anon/authenticated too) at creation time
-- -- revoking from "public" alone is not enough to keep anon out, since
-- anon's own grant doesn't come through the public pseudo-role.
revoke all on function public.join_company_as_member(text) from public, anon;
grant execute on function public.join_company_as_member(text) to authenticated;


-- ===== 20260104000100_harden_function_grants.sql =====
-- Hardening found while adding the public booking surface: a newly created
-- function gets EXECUTE granted to PUBLIC *and*, on this project's default
-- privileges, directly to anon/authenticated at creation time (the same
-- thing a real Supabase project does out of the box). Every earlier
-- migration's `revoke all ... from public` only revoked from the public
-- pseudo-role -- anon's own direct grant was untouched, so anon could call
-- every "authenticated-only" function below. None of them could actually
-- do anything as anon (each checks auth.uid() itself, or is SECURITY
-- INVOKER so RLS still applies inside it), so nothing was ever exploitable
-- -- but anon shouldn't be able to reach them at all. Tightened here rather
-- than quietly left, and test/rls/public-booking.test.ts is what caught it.
revoke execute on function public.current_company_ids() from anon;
revoke execute on function public.current_role_in_company(uuid) from anon;
revoke execute on function public.is_staff_in_company(uuid) from anon;
revoke execute on function public.my_account_ids() from anon;
revoke execute on function public.create_company(text, text, text, text, text) from anon;
revoke execute on function public.vehicle_profit_report(uuid, timestamptz, timestamptz) from anon;


-- ===== 20260104000200_notification_types.sql =====
-- Phase 0's notification_type enum didn't anticipate "booking confirmed" --
-- the closest existing value (pickup_reminder) means something different
-- (a reminder sent close to pickup time, not the initial confirmation).
alter type public.notification_type add value if not exists 'reservation_confirmed';


-- ===== 20260105000000_explicit_grants.sql =====
-- Every earlier migration relied on Supabase's default of auto-granting new
-- public tables to the Data API roles. A project can turn that off
-- (auto_expose_new_tables = false), and then the authenticated role can't
-- touch a single table -- RLS never even gets a chance to run. Granting
-- explicitly makes the schema work either way. RLS is still what decides
-- which rows each caller sees; these grants only let the request reach it.
--
-- anon deliberately gets nothing here: everything public goes through the
-- curated SECURITY DEFINER functions in 20260104000000_public_booking.sql.
grant usage on schema public to anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema public to authenticated, service_role;
grant usage, select on all sequences in schema public to authenticated, service_role;


-- ===== 20260105000100_revoke_anon_table_grants.sql =====
-- Supabase's default privileges grant anon full access to every new table in
-- public. RLS (all policies are `to authenticated`) already returns zero rows to
-- anon, but the booking page reaches data only through SECURITY DEFINER
-- functions, so anon never needs table privileges at all. Remove them so a
-- future mistake in a policy can't expose a table to unauthenticated callers.
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;


-- Make the API pick up the new tables/functions immediately.
notify pgrst, 'reload schema';
